Input: {"question": "When was St. John's Evangelical Lutheran Church built?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d00", "start": 0, "end": 3, "text": "St."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d00", "start": 4, "end": 65, "text": "John's Evangelical Lutheran Church (Livingston, New York) St."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d00", "start": 66, "end": 197, "text": "John's Evangelical Lutheran Church is a historic Evangelical Lutheran church at 923 NY 19 in Livingston, Columbia County, New York."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d00", "start": 198, "end": 407, "text": "It was built in 1901-1902 and is a brick building with a medium pitched gable roof, deep bracketed cornice, and semi-engaged tower in the center bay of the front facade in the Late Gothic Revival style church."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d00", "start": 408, "end": 580, "text": "It is a one-story building constructed of red pressed brick and wood frame, a high basement level, a high pitched gable roof, and two prominent towers of different heights."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d00", "start": 581, "end": 607, "text": "The front gable features a"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d01", "start": 0, "end": 212, "text": "It was built in 1901-1902 and is a brick building with a medium pitched gable roof , deep bracketed cornice , and semi-engaged tower in the center bay of the front facade in the Late Gothic Revival style church ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d01", "start": 213, "end": 389, "text": "It is a one-story building constructed of red pressed brick and wood frame , a high basement level , a high pitched gable roof , and two prominent towers of different heights ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d01", "start": 390, "end": 449, "text": "The front gable features a three part pointed arch window ."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d01", "start": 450, "end": 557, "text": "The adjacent cemetery contains approximately 2,200 burials dating from 1821 to the present.It was listed on"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d02", "start": 0, "end": 209, "text": "It was built in 1850-1851 and is a brick building with a medium pitched gable roof, deep bracketed cornice, and semi-engaged tower in the center bay of the front facade in the Late Gothic Revival style church."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d02", "start": 210, "end": 382, "text": "It is a one-story building constructed of red pressed brick and wood frame, a high basement level, a high pitched gable roof, and two prominent towers of different heights."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d02", "start": 383, "end": 441, "text": "The front gable features a three-part pointed arch window."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d02", "start": 442, "end": 533, "text": "The adjacent cemetery contains approximately 2,200 burials dating from 1821 to the present."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d02", "start": 534, "end": 600, "text": "It was listed on the National Register of Historic Places in 1980."}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d03", "start": 0, "end": 3, "text": "St."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d03", "start": 4, "end": 62, "text": "John's Evangelical Lutheran Church (Springfield, Ohio) St."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d03", "start": 63, "end": 173, "text": "John's Evangelical Lutheran Church is a historic Lutheran church in downtown Springfield, Ohio, United States."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d03", "start": 174, "end": 415, "text": "Founded as a German-speaking parish in Springfield's early days, it grew rapidly during its first few decades, and its present large church building was constructed in the 1890s under the direction of one of Springfield's leading architects."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d03", "start": 416, "end": 511, "text": "The congregation remains in the landmark church building, which has been named a historic site."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d03", "start": 512, "end": 651, "text": "Springfield's first Lutheran congregation was organized in May 1841, and a separate group of German Lutherans began meeting soon afterward."}, "D4S7": {"document_number": 4, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d03", "start": 652, "end": 681, "text": "After a period of worshipping"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d04", "start": 0, "end": 233, "text": "[ 7 ] Since construction in the 1890s , it has been one of Springfield 's most distinctive buildings , due in large part to its two front towers — the bell tower is 135 feet ( 41 m ) high , and the principal tower 184 feet ( 56 m ) ."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d04", "start": 234, "end": 363, "text": "By climbing 156 steps to the summit of the principal tower , one gains a panoramic view of the city and surrounding countryside ."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d04", "start": 364, "end": 479, "text": "[ 2 ] : 504 The building 's general plan is that of a streamlined Latin cross , with slight gabled projections near"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d05", "start": 0, "end": 3, "text": "St."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d05", "start": 4, "end": 79, "text": "John 's Lutheran Church in Springfield , Ohio Worship Time - SUNDAY 9AM St."}, "D6S3": {"document_number": 6, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d05", "start": 80, "end": 178, "text": "John 's Evangelical Lutheran Church is a historic Lutheran church in downtown Springfield , Ohio ."}, "D6S4": {"document_number": 6, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d05", "start": 179, "end": 425, "text": "Founded as a German-speaking parish in Springfield 's early days , it grew rapidly during its first few decades , and its present large church building was constructed in the 1890s under the direction of one of Springfield 's leading architects ."}, "D6S5": {"document_number": 6, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d05", "start": 426, "end": 523, "text": "The congregation remains in the landmark church building , which has been named a historic site ."}, "D6S6": {"document_number": 6, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d05", "start": 524, "end": 592, "text": "Springfield 's First Lutheran congregation was organized in May 1841"}, "D7S1": {"document_number": 7, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d06", "start": 0, "end": 24, "text": "process of restoring it."}, "D7S2": {"document_number": 7, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d06", "start": 25, "end": 95, "text": "The congregation was founded as the \"Deutsch Evangelish Lutheraner St."}, "D7S3": {"document_number": 7, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d06", "start": 96, "end": 171, "text": "Johannes\" by German immigrants to Northwest Missouri in the spring of 1860."}, "D7S4": {"document_number": 7, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d06", "start": 172, "end": 380, "text": "This congregation built its first church structure, a wooden building nicknamed the \"Church in the Timber,\" in October 1860 at Hemme's Landing next to the Missouri River, approximately two miles from Corning."}, "D7S5": {"document_number": 7, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d06", "start": 381, "end": 515, "text": "By 1872, the congregation began outgrowing this structure and purchased the land in Corning on which the current structure now stands."}, "D7S6": {"document_number": 7, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d06", "start": 516, "end": 628, "text": "The current brick building was constructed in 1893 by Pete Thull of Rock Port, Missouri and has been in use ever"}, "D8S1": {"document_number": 8, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d07", "start": 0, "end": 22, "text": "the parochial school ."}, "D8S2": {"document_number": 8, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d07", "start": 23, "end": 73, "text": "In 1871 , the congregation joined the Iowa Synod ."}, "D8S3": {"document_number": 8, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d07", "start": 74, "end": 200, "text": "A new brick church was built in 1893 , but in May 1910 , lightning struck the edifice resulting in fire gutting the building ."}, "D8S4": {"document_number": 8, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d07", "start": 201, "end": 309, "text": "The furnishings were saved before the church was completely burnt , leaving only the blackened brick walls ."}, "D8S5": {"document_number": 8, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d07", "start": 310, "end": 397, "text": "In fall of 1910 , a new brick church was built and a clock was installed in the spire ."}, "D8S6": {"document_number": 8, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d07", "start": 398, "end": 479, "text": "A Lutheran parochial school provided education to the congregation ’ s children ."}, "D8S7": {"document_number": 8, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d07", "start": 480, "end": 518, "text": "In 1895 , a new school was built , and"}, "D9S1": {"document_number": 9, "doc_id": "ramdocs-0398-5bd76a4fd3a9:d08", "start": 0, "end": 52, "text": "NYC AGO Home Page | Back to NYC Organ Project List |"}}, "original_cards": [{"doc_id": "ramdocs-0398-5bd76a4fd3a9:d00", "card_id": "ramdocs-0398-5bd76a4fd3a9:d00:c0", "entity": "St. John's Evangelical Lutheran Church", "scope":